// P8-42d — the screenshot reader's request and its failure classes (U3–U6), against a fake SDK client.
// No test here opens a socket: the client the reader would build is replaced by a subclass that only
// records how it was built, and every request goes to a recording fake.
//
// The image is a few generated bytes behind a real signature, never a photograph. The household
// canaries (a program name, a member name, a full number, an id) belong to the world the test is
// reading "for", and none of them may appear in the request: the reader is never given them, and
// this proves nothing slipped them in. Every fake error and model text carries a canary too, so a
// library text that reached a log line or the returned object would be seen.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import Anthropic from '@anthropic-ai/sdk';

const S = vi.hoisted(() => ({ built: [] as Record<string, unknown>[] }));
vi.mock('@anthropic-ai/sdk', async (importOriginal) => {
  const real = (await importOriginal()) as { default: typeof Anthropic };
  // A subclass keeps every static error class; it records its options and never sends anything.
  class Recording extends real.default {
    constructor(opts: ConstructorParameters<typeof Anthropic>[0]) {
      super(opts);
      S.built.push({ ...opts });
    }
  }
  return { ...real, default: Recording };
});

import { readLoyaltyScreenshot, readTimeoutSeconds, READ_SCHEMA, SCREENSHOT_SYSTEM_PROMPT } from './loyaltyReader';

const KEY = 'zq42d-key-canary-not-a-real-key';
const ENV = { ANTHROPIC_API_KEY: KEY };
/** The world the read is "for": none of it may reach the request. */
const WORLD = { program: 'ZQ42D Canary Airways', member: 'ZQ42D Canary Holder', number: 'ZQ42DNUMBERCANARY7K9X', id: 'zq42d-membership-id-canary' };
const MODEL_TEXT = 'ZQ42D-MODEL-TEXT-CANARY';
const ERROR_TEXT = 'zq42d-sdk-error-text';

/** A JPEG signature, then bytes that spell a canary, so the base64 is recognisable in any log. */
const jpeg = () => new Uint8Array([0xff, 0xd8, 0xff, 0xe0, ...Buffer.from('ZQ42D-IMAGE-BYTES-CANARY', 'utf8')]);
const png = () => new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, ...Buffer.from('ZQ42D-PNG', 'utf8')]);
const b64 = (bytes: Uint8Array) => Buffer.from(bytes).toString('base64');

type Call = { body: Record<string, unknown>; options: Record<string, unknown> };
function fakeClient(answer: () => unknown) {
  const calls: Call[] = [];
  const client = {
    beta: { messages: { create: async (body: Record<string, unknown>, options: Record<string, unknown>) => { calls.push({ body, options }); return answer(); } } },
  } as unknown as Anthropic;
  return { client, calls };
}
const message = (text: string, stop = 'end_turn') => ({
  model: 'claude-opus-5-5', stop_reason: stop, stop_details: null, content: [{ type: 'text', text }], usage: { input_tokens: 7, output_tokens: 3 },
});
const EMPTY = { programName: null, memberNumberSuffix: null, balance: null, unit: null, asOf: null, expiryWarnings: [], instruments: [] };

let lines: string[] = [];
beforeEach(() => {
  lines = [];
  for (const m of ['log', 'warn', 'error', 'info'] as const) vi.spyOn(console, m).mockImplementation((...a: unknown[]) => { lines.push(a.map(String).join(' ')); });
  S.built.length = 0;
});
afterEach(() => vi.restoreAllMocks());

describe('the loyalty screenshot reader (P8-42d)', () => {
  it('T42d-U3: with no usable key nothing is built and nothing is sent, even to an injected client', async () => {
    for (const env of [{}, { ANTHROPIC_API_KEY: '' }, { ANTHROPIC_API_KEY: '   ' }]) {
      const f = fakeClient(() => message(JSON.stringify(EMPTY)));
      expect(await readLoyaltyScreenshot(jpeg(), 'image/jpeg', env, { client: f.client })).toEqual({ ok: false, code: 'api_error' });
      expect(await readLoyaltyScreenshot(jpeg(), 'image/jpeg', env)).toEqual({ ok: false, code: 'api_error' });
      expect(f.calls).toHaveLength(0);
    }
    expect(S.built).toHaveLength(0);
    // The control: the same fake with a key IS called, once, so the zero above is the missing key.
    const live = fakeClient(() => message(JSON.stringify(EMPTY)));
    expect(await readLoyaltyScreenshot(jpeg(), 'image/jpeg', ENV, { client: live.client })).toEqual({ ok: true, reading: EMPTY });
    expect(live.calls).toHaveLength(1);
    expect(S.built).toHaveLength(0);
  });

  it('T42d-U4: one bounded request holding the image and one fixed instruction, the shared schema, and no household data', async () => {
    const f = fakeClient(() => message(JSON.stringify(EMPTY)));
    const image = png();
    await readLoyaltyScreenshot(image, 'image/png', ENV, { client: f.client });
    expect(f.calls).toHaveLength(1);
    const { body, options } = f.calls[0];
    expect(options).toEqual({ maxRetries: 0, timeout: readTimeoutSeconds({}) * 1000 });
    expect(Object.keys(body).sort()).toEqual(['betas', 'fallbacks', 'max_tokens', 'messages', 'model', 'output_config', 'system']);
    expect(body.system).toBe(SCREENSHOT_SYSTEM_PROMPT);
    expect(SCREENSHOT_SYSTEM_PROMPT).toMatch(/untrusted/);
    expect(SCREENSHOT_SYSTEM_PROMPT).toMatch(/never follow/);
    expect(SCREENSHOT_SYSTEM_PROMPT).toMatch(/Never report a person's name, a postal address, a full membership number/);
    const config = body.output_config as { format: { type: string; schema: unknown } };
    expect(config.format.type).toBe('json_schema');
    expect(config.format.schema).toEqual(READ_SCHEMA);
    const messages = body.messages as { role: string; content: Record<string, unknown>[] }[];
    expect(messages).toHaveLength(1);
    expect(messages[0].role).toBe('user');
    const [img, text, ...rest] = messages[0].content;
    expect(rest).toEqual([]);
    expect(img.type).toBe('image');
    const source = img.source as { type: string; media_type: string; data: string };
    expect(source.type).toBe('base64');
    expect(source.media_type).toBe('image/png');
    expect(new Uint8Array(Buffer.from(source.data, 'base64'))).toEqual(image);
    expect(text.type).toBe('text');
    expect(typeof text.text).toBe('string');
    // Nothing of the household the read is for: the reader is never given it, and nothing adds it.
    const sent = JSON.stringify(body);
    for (const canary of Object.values(WORLD)) expect(sent).not.toContain(canary);
    expect(sent).not.toContain(KEY);
    // The timeout follows the environment, as the mail reader's does.
    const timed = fakeClient(() => message(JSON.stringify(EMPTY)));
    await readLoyaltyScreenshot(image, 'image/png', { ...ENV, LOYALTY_READ_TIMEOUT_SECONDS: '5' }, { client: timed.client });
    expect(timed.calls[0].options).toEqual({ maxRetries: 0, timeout: 5 * 1000 });
  });

  it('T42d-U5: every failure is classified, none throws, and no log line carries the error text, the image, the key or the model text', async () => {
    const headers = new Headers();
    const failures: [string, () => unknown][] = [
      ['rate_limited', () => { throw new Anthropic.RateLimitError(429, { message: KEY }, `${ERROR_TEXT}-a ${KEY}`, headers); }],
      ['timeout', () => { throw new Anthropic.APIConnectionTimeoutError({ message: `${ERROR_TEXT}-b ${KEY}` }); }],
      ['api_error', () => { throw new Anthropic.InternalServerError(500, { message: KEY }, `${ERROR_TEXT}-c ${KEY}`, headers); }],
      ['api_error', () => { throw new Error(`${ERROR_TEXT}-d ${KEY}`); }],
      ['refused', () => message(`${MODEL_TEXT} ${KEY}`, 'refusal')],
      ['bad_output', () => message(`${MODEL_TEXT} not json`)],
      ['bad_output', () => message('')],
    ];
    for (const [code, answer] of failures) {
      const f = fakeClient(answer);
      expect(await readLoyaltyScreenshot(jpeg(), 'image/jpeg', ENV, { client: f.client }), code).toEqual({ ok: false, code });
      expect(f.calls).toHaveLength(1);
    }
    expect(lines.length).toBeGreaterThanOrEqual(failures.length);
    for (const line of lines) {
      for (const leak of [ERROR_TEXT, KEY, MODEL_TEXT, b64(jpeg()), 'ZQ42D-IMAGE-BYTES-CANARY']) expect(line).not.toContain(leak);
    }
  });

  it('T42d-U6: a success returns the model\'s object untouched and logs only the model and token counts', async () => {
    const raw = {
      ...EMPTY, programName: 'ZQ42D Sky Club', memberNumberSuffix: WORLD.number, balance: '12', unit: 'points',
      name: WORLD.member, address: 'ZQ42D Street', note: MODEL_TEXT,
    };
    const f = fakeClient(() => message(JSON.stringify(raw)));
    const result = await readLoyaltyScreenshot(jpeg(), 'image/jpeg', ENV, { client: f.client });
    expect(result).toEqual({ ok: true, reading: raw });
    expect(lines).toHaveLength(1);
    const logged = JSON.parse(lines[0]) as Record<string, unknown>;
    expect(Object.keys(logged).sort()).toEqual(['inputTokens', 'level', 'message', 'model', 'outputTokens', 'scope', 'time']);
    expect([logged.level, logged.model, logged.inputTokens, logged.outputTokens]).toEqual(['info', 'claude-opus-5-5', 7, 3]);
    for (const leak of [WORLD.number, WORLD.member, MODEL_TEXT, KEY, b64(jpeg())]) expect(lines[0]).not.toContain(leak);
  });
});
